/*
 *   Find discrete logarithms using Pollard's rho method.
 *   Suitable primes are generated by "genprime" program
 *
 *   See "Monte Carlo Methods for Index Computation"
 *   by J.M. Pollard in Math. Comp. Vol. 32 1978 pp 918-924
 *
 *   Requires: big.cpp crt.cpp
 */

#include <iostream>
#include <vector>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <csignal>

#include "miracl/big.h"   /* include MIRACL system */
#include "miracl/crt.h"   /* chinese remainder thereom */
#include "randomc.h"
#include "genprime.h"

static int NPRIMES=15;
static int PROOT=2;

using namespace std;

Miracl precision=100;

static Big p,p1,order,lim1,lim2;
static BOOL flag=FALSE;

void timeout(int signal_num);

void iterate(Big &x,Big &q,Big &r,Big &a,Big &b)
{
	/* apply Pollards random mapping */
	if (x<lim1)
	{
		x=(x*q)%p;
		a+=1;
		if (a==order) a=0;
		return;
	}
	if (x<lim2)
	{
		x=(x*x)%p;
		a*=2;
		if (a>=order) a-=order;
		b*=2;
		if (b>=order) b-=order;
		return;
	}
	x=(x*r)%p;
	b+=1;
	if (b==order) b=0;
}

long rho(Big &q,Big &r,Big &m,Big &n)
{
	/* find q^m = r^n */
	long iter,rr,i;
	Big ax,bx,ay,by,x,y;
	x=1;
	y=1;
	iter=0L;
	rr=1L;
	do
	{
		/* Brent's Cycle finder */
		x=y;
		ax=ay;
		bx=by;
		rr*=2;
		for (i=1; i<=rr; i++)
		{
			iter++;
			iterate(y,q,r,ay,by);
			if (x==y) break;
		}
	}
	while (x!=y);
	m=ax-ay;
	if (m<0) m+=order;
	n=by-bx;
	if (n<0) n+=order;
	return iter;
}

int main(int argc, char* argv[])
{
	int i,np,sumOfIterations=0;
	long iter, time_taken;
	Big pp[NPRIMES],rem[NPRIMES];
	Big m,n,Q,R,y,w,x;

	p1=Big(1);
	np = atoi(argv[1]);
	for (i=0; i<np; i++)
		pp[i] = Big(argv[i+2]);
	for (i=0; i<np; i++)
		p1*=pp[i];
	p=p1+1;
	if (!prime(p))
	{
		// Modulus is not prime!
		cerr << "M:" << endl;
		return 0;
	}
	else
		cout << "P:" << p << endl;
	lim1=p/3;
	lim2=2*lim1;
	/* solve y = 2^x (mod p) given x and p */
	y = Big(argv[np+2]);
	cout << "Y:" << y << endl;
	time_taken = clock();
	Crt chinese(np,pp);
	for (i=0; i<np; i++)
	{
		/* accumulate solutions for each pp */
		w=p1;
		w/=pp[i];
		Q=pow(y,w,p);
		R=pow(PROOT,w,p);
		order=pp[i];
		iter=rho(Q,R,m,n);
		w=inverse(m,order);
		rem[i]=(w*n)%order;
		sumOfIterations += iter;
	}
	x=chinese.eval(rem);   /* apply Chinese remainder thereom */
	w=pow(PROOT,x,p);
	if ((x == Big(0)) || (w != y))
	{
		cerr << "F:" << endl;
		return 0;
	}
	cout << "X:" << x << endl;
	cout << "C:" << y << endl;
	cout << "I:" << sumOfIterations << endl;
	time_taken = clock()-time_taken;
	cout << "T:" << (float)time_taken/CLOCKS_PER_SEC << endl;
	return 0;
}

void timeout(int signal_num)
{
	cerr << "X:" << endl;
	exit(0);
}
